"""Original authored questions and reproducible, mathematically checked practice variants."""
import json,math,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[1]
ledger=json.loads((root/'provenance.json').read_text());sources={s['id']:s for s in ledger};questions=[]
def q(id,format,topic,prompt,options,correct,explanation,source='mit-algorithms',difficulty='medium',**extra):
 if source!='original-audio':assert sources[source]['status']=='acquired',source
 questions.append(dict(id=id,format=format,topic=topic,prompt=prompt,options=options,correct=correct,explanation=explanation,sourceId=source,sourceURL=sources.get(source,{}).get('url',''),difficulty=difficulty,**extra))
q('binary-search','multiple_choice','Algorithms','A sorted array doubles in size. How does the worst-case number of binary-search comparisons grow?',['It roughly doubles','It increases by about one','It stays exactly the same','It grows quadratically'],['It increases by about one'],'Binary search discards roughly half of the remaining search space at each step. Doubling the input adds about one step.')
q('python-sets','multiple_select','Programming','Which two expressions produce a set?',['set([1, 2])','{1, 2}','[1, 2]','(1, 2)'],['set([1, 2])','{1, 2}'],'A set constructor and a nonempty curly-brace literal create sets. Square brackets create a list; parentheses here create a tuple.','python','easy')
q('thread-memory','true_false','Operating systems','Threads in the same process normally share an address space.',['True','False'],['True'],'Threads share the process address space but maintain their own execution state and stacks.','ostep','easy')
q('stack-blank','fill_blank','Programming','A last-in, first-out collection is called a ____.',[],['stack'],'A stack returns the most recently pushed item first. Python lists support this using append and pop.','python','easy',labels=['Collection name'])
q('raft-election','short_answer','Distributed systems','Explain how Raft elects a leader and reduces split votes.',[],['randomized|random','majority|quorum','term'],'Candidates increment their term and request votes. A majority elects a leader; randomized election timeouts reduce repeated split votes.','raft','hard',criteria=['randomized|random','majority|quorum','term'],rubric='Award exactly one point for each of the following five independently expressed facts. Do not infer unstated facts: 1. A follower starts an election after its election timeout. 2. The candidate increases its term. 3. The candidate votes for itself and requests votes. 4. A majority of votes elects the leader. 5. Randomized election timeouts reduce repeated split votes.')
q('structures-match','matching','Programming','Match each collection to its defining behavior.',['Last in, first out','Unique elements','First in, first out'],['Last in, first out','First in, first out','Unique elements'],'Stacks are LIFO, queues are FIFO, and sets store distinct elements.','python',labels=['Stack','Queue','Set'])
q('isolation-buckets','categorization','Databases','Sort each scenario into its transaction anomaly.',['Read an uncommitted value','Re-read a changed committed value','Re-run a range query and find additional rows'],['Dirty read','Nonrepeatable read','Phantom read'],'The anomalies differ in whether a value was committed, a previously read row changed, or the matching set of rows changed.','postgres',groups=['Dirty read','Nonrepeatable read','Phantom read'])
q('bfs-order','ordering','Algorithms','Order one BFS expansion for an unseen neighbor.',['Enqueue the neighbor','Mark the neighbor visited','Dequeue a vertex','Inspect a neighbor'],['Dequeue a vertex','Inspect a neighbor','Mark the neighbor visited','Enqueue the neighbor'],'Mark a neighbor before enqueuing it so other edges do not enqueue it again.')
q('python-dropdown','dropdown','Programming','Choose the Python collection that removes duplicate values.',['list','set','tuple','str'],['set'],'Sets represent distinct elements. They do not preserve duplicate occurrences.','python','easy',context='unique_values = ____ (values)')
q('raft-quorum','numeric','Distributed systems','How many votes form a majority in a seven-node Raft cluster?',[],['4'],'A strict majority is floor(n / 2) + 1, so seven nodes require four votes.','raft','easy',tolerance=0)
q('storage-visual','visual','Databases','Select the component responsible for durable records.',['Client','API','Cache','Database'],['Database'],'The database is the durable system of record in this simplified architecture. A cache holds replaceable copies.','postgres','easy')
q('python-drag','drag_drop','Programming','Drop the function that returns a new sorted list.',['reversed','sorted','len','sum'],['sorted'],'sorted returns a new list. list.sort changes a list in place and returns None.','python','easy',context='result = ____ ([3, 1, 2])',labels=['Function'])
q('audio-pulses','audio','Programming','Listen to this original signal. How many separate pulses do you hear?',['2','3','4','5'],['3'],'The signal contains three distinct pulses. Counting events is a simple form of discrete signal processing.','original-audio','easy',audioAsset='pulses')
q('falling-complexity','game_2d','Algorithms','Catch the block showing merge sort’s worst-case time complexity.',['O(n²)','O(n log n)','O(2ⁿ)','O(n!)'],['O(n log n)'],'Merge sort has logarithmically many levels; each level processes a total of n elements.',game=dict(template='falling_blocks',params=dict(speed=1.0)))
q('architecture-3d','game_3d','Databases','Tap the database cylinder in this small system.',['Client','API','Database','Queue'],['Database'],'The cylinder represents durable database storage. Rotate the scene to inspect the components.','postgres','easy',game=dict(template='system_architecture',params=dict(roles={'Client':'box','API':'box','Database':'cylinder','Queue':'box'})))
q('live-majority','live','Distributed systems','A five-node cluster needs how many votes to elect a Raft leader?',['2','3','4','5'],['3'],'A majority of five is three. Any two majorities overlap.','raft','easy')
q('mutex-homework','homework','Operating systems','Explain how a mutex can prevent a lost update to a shared counter.',[],['mutual exclusion|one thread','critical section|lock','read|update'],'Protect the entire read-modify-write operation with the same mutex. Mutual exclusion prevents threads from interleaving the critical section.','ostep',criteria=['mutual exclusion|one thread','critical section|lock','read|update'],rubric='Award exactly one point for each of the following five independently expressed facts. Do not infer unstated facts: 1. All writers use the same mutex. 2. Acquire the mutex before reading the counter. 3. Keep the read-modify-write operation inside the critical section. 4. Release the mutex after writing. 5. Mutual exclusion prevents concurrent execution of the protected operation.',dueAt='2026-12-31T23:59:59Z')
q('retry-collaborative','collaborative','Distributed systems','Work together: how can a service avoid applying a retried request twice?',[],['identifier|idempotency|serial','store|cache|record','duplicate|retry'],'Give each request a stable identifier, record its result, and return that result when the same request is retried.','raft',criteria=['identifier|idempotency|serial','store|cache|record','duplicate|retry'],rubric='Award exactly one point for each of the following five independently expressed facts. Do not infer unstated facts: 1. Use a stable unique request identifier. 2. Store the result associated with that identifier. 3. Detect repeated identifiers. 4. Return the stored result for a duplicate. 5. Atomically record the identifier with the effect to prevent races.')
# Original concept questions, grounded in the cited open sources.
for index,(id,topic,prompt,options,explanation,source) in enumerate(json.loads((root/'content/concepts.json').read_text())):
 correct=[options[0]]
 shift=index%len(options)
 options=options[shift:]+options[:shift]
 q(id,'multiple_choice',topic,prompt,options,correct,explanation,source)
# Parameterized exercises are deliberately labeled; they are not unique research concepts.
for n in range(3,102,2):
 q(f'quorum-{n}','numeric','Distributed systems',f'A Raft cluster has {n} voting nodes. What is its strict-majority quorum?',[],[str(n//2+1)],f'floor({n}/2) + 1 = {n//2+1}.','raft','easy',tolerance=0,generation='parameterized')
for n in range(2,102):
 q(f'graph-edges-{n}','numeric','Algorithms',f'How many edges are in a simple undirected complete graph with {n} vertices?',[],[str(n*(n-1)//2)],f'Each unordered pair contributes one edge: {n} × {n-1} / 2 = {n*(n-1)//2}.',tolerance=0,generation='parameterized')
for a in range(2,32):
 for b in range(2,32):
  q(f'loops-{a}-{b}','numeric','Programming','How many times does emit() run?',[],[str(a*b)],f'The inner loop runs {b} times for each of {a} outer iterations: {a*b} calls.','python','easy',context=f'for i in range({a}):\n    for j in range({b}):\n        emit()',tolerance=0,generation='parameterized')
for k in range(1,21):
 q(f'halving-{k}','numeric','Algorithms',f'Start with {2**k} elements. After how many exact halvings is one element left?',[],[str(k)],f'2 to the power {k} is {2**k}, so {k} halvings leave one.',tolerance=0,generation='parameterized')
assert len({x['id'] for x in questions})==len(questions)
assert len({x['format'] for x in questions})==18
(root/'content/questions.json').write_text(json.dumps(questions,ensure_ascii=False,indent=2)+'\n')
print(len(questions),'questions across',len({x['format'] for x in questions}),'formats')
